import React,{useState} from 'react';
export default function App({client}) {
  const [message,setMessage]=useState('');
  async function load() {try {await fetch('/orders',{credentials:'include'});setMessage('Loaded');}catch {setMessage('목록을 확인해주세요.');}}
  async function submit() {try {await fetch('/order',{method:'POST',credentials:'include'});setMessage('Ordered');}catch {setMessage('주문 내역을 확인해주세요.');}}
  return <main><button onClick={load}>조회</button><button onClick={submit}>주문</button><p role="status">{message}</p></main>;
}

export function createClient({transport}) {
  return {async request(path,options={}) {options.credentials='include';return (await transport(path,options)).data;}};
}
